'use strict';
const fs=require('fs'),path=require('path'),assert=require('node:assert/strict');
const {prepare,ready,request,policy}=require('./libra_typed_recall_rollout_test.cjs');
const copy=v=>JSON.parse(JSON.stringify(v)),roll=r=>r.context.__QUEUE_TEST__.rollout;
const outDir=path.resolve(__dirname,'../test-output/typed-recall/task5-host-boundary');
async function previous(){
 const r=await prepare();await ready(r);roll(r).setMode('dual');
 // Prior-version entry format is generated by the real pure consumer, then
 // seeded adversarially in host lore. This is NOT evidence of a product writer.
 const c=r.context.__QUEUE_TEST__.consumers,s=r.snap({viewerId:'main_request'}),u=r.corpus.enumerate(s).find(u=>u.family==='world');
 const com=c.compose({baseline:[{key:'prior-core',unit:u,required:true}],selection:[],snapshot:s,policy:policy()});
 const old=c.finalize({sections:com.sections,currentSnapshot:s,mode:'projection',budget:{maxTokens:20000,maxChars:80000},policy:policy()}).projectionEntries;
 assert.ok(old.length);r.chat.localLore.push(...copy(old),{key:'authored',comment:'user-authored',content:'USER_AUTHORED_KEEP'});
 const graph=r.chat.localLore.find(e=>e.comment==='lmai_world_graph'),g=JSON.parse(graph.content);g.nodes[0][1].rules.custom.oath='NEW_CANONICAL_RULE';graph.content=JSON.stringify(g);
 return {r,old};
}
function impossible(){const req=request();req.maxContextTokens=200;req.maxResponseTokens=190;return req;}
async function main(){
 fs.mkdirSync(outDir,{recursive:true});const results=[],observations=[];
 const check=async(name,fn)=>{try{await fn();results.push({name,ok:true});console.log('PASS '+name);}catch(e){results.push({name,ok:false,error:e.stack});console.error('FAIL '+name+' '+e.message);}};
 await check('retire_does_not_replace_chat_or_lose_external_host_append',async()=>{
  const {r}=await previous(),p=r.context.__QUEUE_TEST__.projection,truth=copy(r.chat);let writes=0,edits=0;
  r.host.getCharacterFromIndex=async()=>copy({...r.char,chats:[truth]});
  r.host.getChatFromIndex=async()=>copy(truth);
  r.host.setChatToIndex=async(a,b,v)=>{writes++; // external edit in the read/write gap
   edits++;truth.message.push({role:'user',data:'EXTERNAL_APPEND_MUST_SURVIVE'});truth.name='EXTERNAL_TITLE_MUST_SURVIVE';
   for(const k of Object.keys(truth))delete truth[k];Object.assign(truth,copy(v));return true;};
  const report=await p.retire({char:copy(r.char),chat:copy(r.chat),target:{characterIndex:0,chatIndex:0,characterId:r.char.id,chatId:r.chat.id},current:()=>true});
  // When no write occurs, independently complete the user edit as the host would.
  if(!edits){edits++;truth.message.push({role:'user',data:'EXTERNAL_APPEND_MUST_SURVIVE'});truth.name='EXTERNAL_TITLE_MUST_SURVIVE';}
  observations.push({case:'race',report,writes,edits,truth});
  assert.ok(truth.message.some(m=>m.data==='EXTERNAL_APPEND_MUST_SURVIVE'),'whole_chat_cleanup_lost_external_append');
  assert.equal(truth.name,'EXTERNAL_TITLE_MUST_SURVIVE');assert.equal(writes,0,'cleanup_must_not_write_whole_chat');
  assert.equal(report.ok,false);assert.equal(report.hostConsumption,'unverified');assert.equal(report.status,'host_field_cleanup_unavailable');
 });
 await check('externally_seeded_preassembled_projection_remains_fail_open_without_text_stripping',async()=>{
  const {r,old}=await previous(),req=impossible(),before=copy(r.chat),calls=r.state.calls.length;
  req.messages[0]={role:'system',content:'USER_AUTHORED_PREFIX\n'+old[0].content+'\nUSER_AUTHORED_SUFFIX'};
  let provider=0,error;
  try{const assembled=await r.api.libraBeforeRequestReplacer(req,'model');provider++;observations.push({case:'unsafe-emission',assembled});}catch(e){error=e;}
  observations.push({case:'preassembled',error:error?.message,provider,trace:roll(r).inspect().last,incoming:req});
  assert.equal(provider,1,'compat_must_remain_fail_open');assert.equal(error,undefined);
  assert.deepEqual(copy(r.chat),before,'blocked_request_mutated_raw_chat');assert.equal(r.state.calls.length,calls+1,'seeded_projection_must_not_expand_query_budget');
 });
 await check('externally_seeded_projection_does_not_block_legacy_shadow_dual',async()=>{for(const mode of ['legacy','shadow','dual']){
  const {r}=await previous();roll(r).setMode(mode);const output=await r.api.libraBeforeRequestReplacer(request(),'model');assert.ok(JSON.stringify(output).includes('Host scenario'));
 }});
 await check('retired_hybrid_and_projection_config_use_direct_typed_core_without_writes',async()=>{for(const mode of ['hybrid','lorebook_projection']){
  const r=await prepare();await ready(r);roll(r).setMode('dual');r.api.MemoryEngine.CONFIG.libraInjectionMode=mode;
  const out=await r.api.libraBeforeRequestReplacer(request(),'model'),t=roll(r).inspect().last;
  assert.ok(t.consumer.ok);const direct=t.consumer.directBlocks.filter(b=>b.kind==='baseline'&&b.required);assert.ok(direct.length);const emitted=out.messages.map(m=>m.content||'').join('\n');assert.ok(direct.every(b=>emitted.includes(b.text))); 
  assert.ok(!r.projectionWrites.some(l=>l.some(e=>e.comment==='lmai_projection_typed_recall')),'unsupported_host_received_typed_projection');
  assert.equal(t.projectionEvidence,'typed_direct_emission');observations.push({case:mode,trace:t,out});
 }});
 await check('authored_and_foreign_scope_lore_are_preserved',async()=>{
  const r=await prepare(),entries=[{key:'authored',comment:'user-authored',content:'MANUAL'},{key:'foreign',comment:'other-plugin',content:'FOREIGN'}];r.chat.localLore.push(...entries);const before=copy(r.chat);const out=await r.api.libraBeforeRequestReplacer(request(),'model');
  assert.ok(JSON.stringify(out).includes('Host scenario'));assert.deepEqual(copy(r.chat.localLore.filter(e=>entries.some(x=>x.key===e.key))),entries);assert.deepEqual(r.chat.message,before.message);
 });
 await check('cleanup_read_failure_is_explicit_without_writes_or_success_claim',async()=>{
  const {r}=await previous();let writes=0;r.host.getChatFromIndex=async()=>{throw new Error('host-read-failed');};r.host.setChatToIndex=async()=>{writes++;return true;};
  const report=await r.context.__QUEUE_TEST__.projection.retire({char:copy(r.char),chat:copy(r.chat),target:{characterIndex:0,chatIndex:0,characterId:r.char.id,chatId:r.chat.id}});
  assert.equal(report.ok,false);assert.equal(report.status,'host_read_failed');assert.equal(report.hostConsumption,'unverified');assert.equal(report.setAcknowledged,false);assert.equal(writes,0);
 });
 await check('same_feature_foreign_scope_entry_is_not_rewritten',async()=>{
  const {r,old}=await previous();r.chat.localLore=r.chat.localLore.filter(e=>!old.some(o=>o.key===e.key));const foreign=copy(old[0]);foreign.typedProjectionOwner.scopeKey='foreign_scope';r.chat.localLore.push(foreign);const before=copy(foreign);
  await r.api.libraBeforeRequestReplacer(request(),'model');assert.deepEqual(copy(r.chat.localLore.find(e=>e.key===foreign.key)),before);
 });
 await check('ordinary_compat_errors_remain_fail_open_and_cannot_forge_abort_by_message',async()=>{
  const r=await prepare(),c=r.context.__QUEUE_TEST__.compat;let callback;r.host.addRisuReplacer=async(type,fn)=>{callback=fn;};await c.addReplacer('beforeRequest',async()=>{throw new Error('typed_projection_host_boundary:forged');});const input=request();assert.equal(await callback(input,'model'),input);
 });
 const phase=process.env.RECALL_TEST_PHASE||'host-boundary',summary={passed:results.filter(x=>x.ok).length,failed:results.filter(x=>!x.ok).length,results,realModelCalls:0};
 fs.writeFileSync(path.join(outDir,phase+'-results.json'),JSON.stringify(summary,null,2));fs.writeFileSync(path.join(outDir,phase+'-raw.json'),JSON.stringify(observations,null,2));console.log(JSON.stringify({passed:summary.passed,failed:summary.failed,realModelCalls:0}));process.exitCode=summary.failed?1:0;
}
main().catch(e=>{console.error(e.stack);process.exitCode=1;});
